{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Codeine, the closest analogue sharing the morphinan scaffold, 3-methoxy group, tertiary amine, and 6-hydroxyl, has absolute oral bioavailability of 42–71% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Codeine sulfate in healthy subjects showed oral bioavailability of 80.5%, further supporting high oral bioavailability for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ethylmorphine, a 3-ethoxy analogue, had median systemic availability of 0.74 (range 0.54–0.92) after oral dosing, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Diacetylmorphine, a more lipophilic morphinan prodrug, showed oral bioavailability of 45.6–64.5% in opioid-dependent subjects, supporting high F for this alkaloid family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Morphine itself can show borderline oral bioavailability (e.g., 19.6% in one absolute study), but this is less transferable because the free 3-phenolic OH undergoes extensive glucuronidation, whereas the query is 3-methoxy-substituted like codeine.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 3-methoxy morphinan alkaloid closely related to codeine. Codeine and close analogues consistently show oral bioavailability well above 20% (approximately 40–80%). The lower values seen for morphine are attributable to the free 3-phenolic OH, which is methylated in the query, reducing first-pass glucuronidation. Therefore, F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query stereoisomer.",
    "The query's precise identity (e.g., codeine vs a stereoisomer such as neopine) and its human metabolic profile are not experimentally characterized.",
    "Codeine bioavailability varies across studies (40–84%), and first-pass metabolism may differ with stereochemistry."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

